using UnityEngine;
using UnityEditor;
using System;
using System.IO;
using System.Text;
using ConRoi.Investigation.V36.R103;
using Object = UnityEngine.Object;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            var s = Object.FindFirstObjectByType<InvestigationSession>();
            if (!EditorApplication.isPlaying || !s.data.returnedToWorkshop)
                throw new Exception("Completed controller route required");
            s.SaveDirectoryOverride = Path.GetFullPath("Test/KetQua/investigation_r103/layout-profile");
            var w = EditorWindow.GetWindow(Type.GetType("UnityEditor.GameView,UnityEditor"));
            var pages = new[]{"shoeprint", "shoe", "shoecontrol", "fabric", "coat", "mechanism", "cipher", "compare", "reconstruction", "conclusions"};
            int resolution = 0, step = -1;
            double next = 0;
            var log = new StringBuilder("Layout fixtures: API opens known pages/acquires sample cards only. Not gameplay/consent/solution evidence. Screens reviewed separately.\n");
            EditorApplication.CallbackFunction update = null;
            update = () =>
            {
                if (EditorApplication.timeSinceStartup < next)
                    return;
                next = EditorApplication.timeSinceStartup + 1.2;
                try
                {
                    if (step == -1)
                    {
                        var size = resolution == 0 ? new Vector2(1024, 597.2f) : new Vector2(1536, 885.2f);
                        w.minSize = w.maxSize = size;
                        w.position = new Rect(0, 30, size.x, size.y);
                        w.Focus();
                        step = 0;
                        return;
                    }

                    if (step > 0)
                    {
                        string tag = resolution == 0 ? "720" : "1080";
                        ScreenCapture.CaptureScreenshot("Test/BangChung/investigation_r103/ui-" + tag + "-" + pages[step - 1] + ".png");
                        log.AppendLine(tag + " " + pages[step - 1] + " " + Screen.width + "x" + Screen.height);
                    }

                    if (step == pages.Length)
                    {
                        if (resolution == 0)
                        {
                            resolution = 1;
                            step = -1;
                            return;
                        }

                        EditorApplication.update -= update;
                        File.WriteAllText("Test/KetQua/investigation_r103/ui-layout.txt", log.ToString());
                        return;
                    }

                    string page = pages[step];
                    if (step < 6)
                    {
                        s.Acquire(page);
                        s.OpenEvidence(page);
                    }
                    else
                        s.OpenPage(page);
                    step++;
                }
                catch (Exception e)
                {
                    log.AppendLine("FAIL " + e);
                    EditorApplication.update -= update;
                    File.WriteAllText("Test/KetQua/investigation_r103/ui-layout.txt", log.ToString());
                }
            };
            EditorApplication.update += update;
            r.Log("Started bounded two-resolution page capture (~30s)");
        }
    }
}

